// ---------------------------------------------------------------------------
// Party Cassette — generated by Dialcraft
// target: Amazfit Bip 6 (bip-6, 390×450, s)
//
// Built against the Zepp OS watchface API:
//   widgets  https://docs.zepp.com/docs/watchface/api/hmUI/widget/
//   layout   px() scales from app.json designWidth = 390
//   states   show_level = normal / AOD / edit
// Design-spec reminders: preview time 10:09:36, 2px safe edge, AOD keeps
// the pixel budget under 10% with a black background and no second hand.
// ---------------------------------------------------------------------------
import ui from '@zos/ui'

const A = (p) => `images/${p}`

// ---- image arrays (frame order matters: digits 0-9, week 1-7) ----
const img_Hour_j139 = [
  A('pc/c0.png'),
  A('pc/c1.png'),
  A('pc/c2.png'),
  A('pc/c3.png'),
  A('pc/c4.png'),
  A('pc/c5.png'),
  A('pc/c6.png'),
  A('pc/c7.png'),
  A('pc/c8.png'),
  A('pc/c9.png'),
]

const img_Battery_fjti = [
  A('pc/t0.png'),
  A('pc/t1.png'),
  A('pc/t2.png'),
  A('pc/t3.png'),
  A('pc/t4.png'),
  A('pc/t5.png'),
  A('pc/t6.png'),
  A('pc/t7.png'),
  A('pc/t8.png'),
  A('pc/t9.png'),
]

const img_Hour_AOD_k1ep = [
  A('pc/a0.png'),
  A('pc/a1.png'),
  A('pc/a2.png'),
  A('pc/a3.png'),
  A('pc/a4.png'),
  A('pc/a5.png'),
  A('pc/a6.png'),
  A('pc/a7.png'),
  A('pc/a8.png'),
  A('pc/a9.png'),
]

WatchFace({
  initView() {
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Scene (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('pc/bg.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Reel left (IMG)
    W.reel0 = ui.createWidget(ui.widget.IMG, {
      x: px(97),
      y: px(172),
      center_x: px(121),
      center_y: px(196),
      src: A('pc/reel0.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Reel right (IMG)
    W.reel1 = ui.createWidget(ui.widget.IMG, {
      x: px(244),
      y: px(179),
      center_x: px(268),
      center_y: px(203),
      src: A('pc/reel1.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(42),
      hour_startY: px(295),
      hour_zero: 1,
      hour_space: px(8),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_j139,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Colon (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(180),
      y: px(295),
      src: A('pc/colon.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(219),
      minute_startY: px(295),
      minute_zero: 1,
      minute_space: px(8),
      minute_align: ui.align.LEFT,
      minute_array: img_Hour_j139,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Cassette edge (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(31),
      y: px(283),
      src: A('pc/edge.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Battery (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(3),
      y: px(386),
      w: px(390),
      type: ui.data_type.BATTERY,
      font_array: img_Battery_fjti,
      align_h: ui.align.CENTER_H,
      unit_en: A('pc/unit.png'),
      unit_sc: A('pc/unit.png'),
      unit_tc: A('pc/unit.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(42),
      hour_startY: px(193),
      hour_zero: 1,
      hour_space: px(8),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_AOD_k1ep,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon AOD (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(180),
      y: px(193),
      src: A('pc/colon_a.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Minute AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(219),
      minute_startY: px(193),
      minute_zero: 1,
      minute_space: px(8),
      minute_align: ui.align.LEFT,
      minute_array: img_Hour_AOD_k1ep,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })


    // ---- user code (project.userCode) ----
    // <reels>
    // The two cassette reels turn slowly (25 degrees a second), driven by the clock so the turn is smooth after a pause. Only while the screen is on.
    {
      let timer = null;
      const upd = () => { try { const a = ((Date.now() / 1000) * 25) % 360; W.reel0.setProperty(ui.prop.ANGLE, a); W.reel1.setProperty(ui.prop.ANGLE, a); } catch (e) {} };
      const stop = () => { if (timer) { clearTimeout(timer); timer = null; } };
      const tickNext = () => { upd(); timer = setTimeout(tickNext, 100); };
      const start = () => { stop(); tickNext(); };
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { pause_call: stop, resume_call: start });
      start();
    }
    // </reels>

    // ---- screen corners (the face switcher draws the live face square) ----
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(0), w: px(86), h: px(86), src: A('corner_tl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(0), w: px(86), h: px(86), src: A('corner_tr.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(0), y: px(364), w: px(86), h: px(86), src: A('corner_bl.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
    ui.createWidget(ui.widget.IMG, { x: px(304), y: px(364), w: px(86), h: px(86), src: A('corner_br.png'), show_level: ui.show_level.ONLY_NORMAL | ui.show_level.ONLY_AOD })
  },

  build() {
    this.initView()
  },
})
